<script setup lang="ts">
import {computed,reactive,ref,watch,onUnmounted} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useWorkbench} from '../stores/workbench'
import {stages,statusNames,validApproval,fingerprint,projectActive,uid,type Asset,type Task} from '../lib/domain'
import Icon from '../components/Icon.vue'
import Dialog from '../components/Dialog.vue'
import ModelDefaultSelect from '../components/ModelDefaultSelect.vue'
const emit=defineEmits<{create:[]}>(),route=useRoute(),router=useRouter(),store=useWorkbench(),query=ref(''),idea=ref(''),taskFilter=ref('ALL'),taskToDelete=ref<Task|null>(null),preview=ref<{url:string;asset:Asset}|null>(null),libraryProjectId=ref('')
const section=computed(()=>String(route.params.section)),meta:Record<string,{title:string;subtitle:string;eyebrow:string}>={ideas:{title:'灵感收件箱',subtitle:'先收下那些转瞬即逝的念头，再慢慢找到表达。',eyebrow:'好作品，常常从一个小问题开始'},workflow:{title:'每一步，都有着落',subtitle:'49 个制作节点。先选择作品，再进入该作品的节点；也可以只查看通用流程。',eyebrow:'完整的创作地图'},library:{title:'你的创作资产',subtitle:'留下可复用的素材、参考与完成过的表达。',eyebrow:'每一次创作，都在积累'},agents:{title:'一个人，也有团队',subtitle:'19 个独立专家包；主管真实委派，评审独立运行。当前用测试模型验收执行链路。',eyebrow:'角色协作，模型自由选择'},tools:{title:'连接你的制作现场',subtitle:'控制台管理全流程，外部工具在合适的机器上执行。',eyebrow:'工具与执行环境'},tasks:{title:'让每一步都可追溯',subtitle:'查看计划检查、执行前提和需要你处理的问题。',eyebrow:'任务中心'},approvals:{title:'重要的事，由你决定',subtitle:'在关键阶段确认确定版本，其他重复工作交给流程。',eyebrow:'六个阶段拍板'},business:{title:'让创作，持续下去',subtitle:'看清真实投入与回报，再决定下一步怎么走。',eyebrow:'副业经营'},settings:{title:'属于你的工作空间',subtitle:'管理数据保存、备份和当前版本的能力边界。',eyebrow:'工作区设置'},'creator-profile':{title:'先认识创作者自己',subtitle:'真实的经历与清晰的方向，是每个作品的起点。',eyebrow:'创作档案'}}
const current=computed(()=>meta[section.value]??meta.settings),profile=reactive<Record<string,string>>({...store.state.profile}),entry=reactive({label:'',amount:0,kind:'cost'})
watch(()=>store.state.profile,p=>Object.assign(profile,p),{deep:true});watch(section,()=>query.value='')
const profileFields=[['resources','能力、经历与可用资源'],['audience','希望帮助的观众'],['positioning','我的账号定位'],['pillars','计划持续创作的栏目'],['account','平台账号与主页说明'],['standard','视觉、声音和制作规范']]
const selectedProject=computed(()=>store.state.projects.find(p=>p.id===route.query.projectId))
const selectedWorkflowNode=computed(()=>store.catalog.nodes.find(n=>n.id===route.query.node))
const stageFilter=computed(()=>String(route.query.stage??''))
const filteredNodes=computed(()=>store.catalog.nodes.filter(n=>(!stageFilter.value||n.stage===stageFilter.value)&&(n.id+n.name).toLowerCase().includes(query.value.toLowerCase())))
const responsibilityCounts=computed(()=>({A:store.catalog.nodes.filter(n=>n.responsibility==='A').length,B:store.catalog.nodes.filter(n=>n.responsibility==='B').length,C:store.catalog.nodes.filter(n=>n.responsibility==='C').length}))
function workflowProject(value:string){router.replace({query:{...route.query,projectId:value||undefined}})}
function openWorkflowNode(id:string){if(selectedProject.value)router.push('/projects/'+selectedProject.value.id+'?node='+id);else router.replace({query:{...route.query,node:id}})}
async function deleteTask(){if(taskToDelete.value&&await store.command({type:'DELETE_TASK',payload:{id:taskToDelete.value.id}},'任务已移到已删除，可随时恢复'))taskToDelete.value=null}

const approvals=computed(()=>store.state.projects.filter(projectActive).flatMap(p=>store.catalog.gates.filter(g=>g.after.every(id=>p.nodes[id].status==='COMPLETED')&&!validApproval(p,g)).map(g=>({project:p,gate:g}))))
const tasks=computed(()=>store.state.tasks.filter(t=>taskFilter.value==='DELETED'?!!t.deletedAt:!t.deletedAt&&(taskFilter.value==='ALL'||t.status===taskFilter.value)))
const income=computed(()=>store.state.ledger.filter(e=>e.kind==='income').reduce((s,e)=>s+e.amount,0)),cost=computed(()=>store.state.ledger.filter(e=>e.kind==='cost').reduce((s,e)=>s+e.amount,0))
const tools=[{name:'ComfyUI',icon:'Workflow',description:'节点式图像、视频与声音素材工作流',kind:'生成式素材'},{name:'FFmpeg / ffprobe',icon:'Film',description:'转码、合成、媒体参数与技术检查',kind:'媒体处理'},{name:'Remotion',icon:'PanelsTopLeft',description:'程序化图文、字幕动画与视频模板',kind:'模板渲染'},{name:'OBS / 浏览器录屏',icon:'MonitorPlay',description:'真实操作、窗口、画面与声音采集',kind:'录屏与实测'},{name:'人工剪辑软件',icon:'Scissors',description:'精剪、调色、声音后期与工程交接',kind:'人工编辑'},{name:'抖音 / 小红书',icon:'Send',description:'发布包交付、真实发布状态与数据导入',kind:'平台交付'}]
async function capture(){if(await store.command({type:'ADD_IDEA',payload:{text:idea.value}},'已存入灵感收件箱'))idea.value=''}
async function fromIdea(text:string){const id=uid('project');if(await store.command({type:'CREATE_PROJECT',payload:{id,title:text.slice(0,28),brief:text,template:'SCREENCAST'}},'已创建作品，选题立项仍需你确认'))router.push('/projects/'+id+'?node=N08')}
const platformNames:Record<string,string>={DOUYIN:'抖音',XIAOHONGSHU:'小红书'}
const platformName=(id:string)=>platformNames[id]??id
async function approve(projectId:string,gateId:string,platform?:string){const p=store.state.projects.find(p=>p.id===projectId)!,g=store.catalog.gates.find(g=>g.id===gateId)!;await store.command({type:'APPROVE_GATE',payload:{projectId,gateId,platform,fingerprint:fingerprint(p,g,platform)}},platform?`${platformName(platform)}平台已确认`:'当前版本已确认')}
async function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;if(file.size>50*1024*1024){store.toast('当前单文件最大 50MB','error');return}try{await store.addAsset(file,libraryProjectId.value)}catch{store.toast('文件保存失败，请检查空间或服务状态','error')}}
async function view(asset:Asset){try{closePreview();preview.value={asset,url:await store.assetUrl(asset)}}catch{store.toast('无法读取素材原件，请检查存储位置','error')}}
function closePreview(){if(preview.value?.url.startsWith('blob:'))URL.revokeObjectURL(preview.value.url);preview.value=null}onUnmounted(closePreview)
</script>
<template><div class="page-content"><div class="page-heading"><div><span class="page-eyebrow">{{current.eyebrow}}</span><h1>{{current.title}}<span class="heading-dot">.</span></h1><p>{{current.subtitle}}</p></div><button v-if="section==='library'" class="btn primary" @click="($refs.assetInput as HTMLInputElement).click()"><Icon name="Upload"/>上传素材</button><button v-if="section==='settings'" class="btn primary" @click="store.exportState()"><Icon name="Download"/>导出工作区</button></div>
<template v-if="section==='ideas'"><section class="idea-composer"><Icon name="Lightbulb" :size="25"/><textarea v-model="idea" placeholder="一个问题、一段经历，或者一个还没想清楚的念头……" rows="3" maxlength="2000"/><div><span class="muted small">{{idea.length}} / 2000 · 仅保存，不调用模型</span><button class="btn primary" :disabled="!idea.trim()" @click="capture"><Icon name="Plus" :size="16"/>收下这个想法</button></div></section><div class="idea-list"><article v-for="i in store.state.ideas.filter(i=>i.text.includes(query))" :key="i.id"><span class="idea-marker"><Icon name="Sparkles" :size="17"/></span><div><p>{{i.text}}</p><small class="muted">{{new Date(i.createdAt).toLocaleString('zh-CN')}}</small></div><button class="btn" @click="fromIdea(i.text)">以此开始<Icon name="ArrowUpRight" :size="15"/></button></article><div v-if="!store.state.ideas.length" class="empty-state small-empty"><Icon name="Inbox" :size="30"/><h3>给下一个好想法，留个位置</h3><p>在上方写下第一条灵感，它会一直保存在这里。</p></div></div></template>
<template v-else-if="section==='workflow'"><section class="workflow-context"><label>流程所属作品<select aria-label="流程所属作品" :value="selectedProject?.id??''" @change="workflowProject(($event.target as HTMLSelectElement).value)"><option value="">通用流程 · 先查看节点说明</option><optgroup label="我的作品"><option v-for="p in store.state.projects.filter(p=>!p.sample)" :key="p.id" :value="p.id">{{p.title}}</option></optgroup><optgroup label="示例作品"><option v-for="p in store.state.projects.filter(p=>p.sample)" :key="p.id" :value="p.id">{{p.title}} · 示例</option></optgroup></select></label><div><b>{{selectedProject?'正在查看：'+selectedProject.title:'当前是通用流程，不属于任何作品'}}</b><p>{{selectedProject?'点击下方节点，将进入此作品对应的产物编辑区。':'点击节点先查看要求，再选择要制作的作品；不会自动进入示例。'}}</p></div><button class="btn" @click="emit('create')"><Icon name="Plus" :size="15"/>新建作品</button></section><div v-if="selectedWorkflowNode" class="workflow-node-preview"><span class="badge neutral">{{selectedWorkflowNode.id}} · 节点说明</span><h2>{{selectedWorkflowNode.name}}</h2><p>{{selectedWorkflowNode.inputDescription}}</p><p><b>完成标准：</b>{{selectedWorkflowNode.acceptanceCriteria}}</p><button class="btn primary" :disabled="!selectedProject" @click="openWorkflowNode(selectedWorkflowNode.id)">{{selectedProject?'在所选作品中打开此节点':'先在上方选择作品'}}</button></div><div class="filter-bar"><span class="muted">{{responsibilityCounts.A}} 个可独立执行 · {{responsibilityCounts.B}} 个人机协作 · {{responsibilityCounts.C}} 个人工主导</span><div class="workflow-filters"><select class="filter-select" aria-label="流程阶段" :value="stageFilter" @change="router.replace({query:{...route.query,stage:($event.target as HTMLSelectElement).value||undefined}})"><option value="">全部阶段</option><option v-for="(name,id) in stages" :key="id" :value="id">{{name}}</option></select><div class="inline-search"><Icon name="Search" :size="15"/><input v-model="query" placeholder="搜索节点或编号" aria-label="搜索流程节点"></div></div></div><div class="workflow-stage" v-for="(name,id) in stages" :key="id" v-show="filteredNodes.some(n=>n.stage===id)"><div class="workflow-stage-heading"><span>{{name}}</span><small>{{filteredNodes.filter(n=>n.stage===id).length}} 个节点</small></div><button class="workflow-row" v-for="node in filteredNodes.filter(n=>n.stage===id)" :key="node.id" @click="openWorkflowNode(node.id)"><code>{{node.id}}</code><b>{{node.name}}</b><span>{{selectedProject?statusNames[selectedProject.nodes[node.id].status]:node.responsibility==='A'?'条件明确可自动执行':node.responsibility==='B'?'人机协作':'人工主导'}}</span><small>{{store.catalog.agents.find(a=>a.id===node.agentRole)?.name}}</small><Icon name="ArrowUpRight" :size="16"/></button></div><p v-if="!filteredNodes.length" class="empty-copy">没有匹配节点，试试其他阶段或关键词。</p></template>
<template v-else-if="section==='agents'"><div class="info-strip"><Icon name="Info"/>当前是角色目录与模型继承配置，独立专家包已加载到真实协作运行服务。当前使用测试模型验证执行链路；专业能力尚未通过领域验收。</div><section class="agent-runtime-explainer"><h2>这些角色现在如何工作？</h2><p>Java 固定业务输入与模型配置 → LangGraph 调度 → Deep Agents 主管通过 task 委派专家 → 专家读取独立 Skill、知识与输入 → 提交候选 → 独立评审 → 返工或等待你采纳。</p><p>协作运行页保存实际工具调用、候选版本、评审和交接记录。19 个专家包已配置；领域专业能力仍需真实模型与人工样本评估。付费调用保持关闭，外部媒体工具仍只提供接入文档。</p><a class="text-link" href="/guides/agent-runtime.md" target="_blank" rel="noopener">阅读实际代码与完整协作设计<Icon name="ArrowUpRight" :size="14"/></a></section><section class="agent-unit" v-for="unit in [...new Set(store.catalog.agents.map(a=>a.workUnit))]" :key="unit"><div class="section-heading"><h2>{{unit}}</h2></div><div class="agent-grid"><article v-for="agent in store.catalog.agents.filter(a=>a.workUnit===unit)" :key="agent.id" class="agent-card"><span class="agent-avatar"><Icon name="Bot" :size="22"/></span><h3>{{agent.name}}</h3><p>{{agent.responsibility}}</p><ModelDefaultSelect scope="AGENT" :agent-id="agent.id" label="角色默认模型"/><label>语言能力单独覆盖<select :value="store.state.agentBindings[agent.id]?.TEXT_REASONING??''" @change="store.command({type:'SET_BINDING',payload:{scope:'AGENT',agentId:agent.id,capability:'TEXT_REASONING',modelId:($event.target as HTMLSelectElement).value}},'Agent 默认模型已保存')"><option value="">继承全局默认</option><option v-for="m in store.state.models.filter(m=>m.capabilities.includes('TEXT_REASONING'))" :key="m.id" :value="m.id">{{m.name}}</option></select></label></article></div></section></template>
<template v-else-if="section==='tools'"><div class="info-strip"><Icon name="Laptop"/>已提供远程媒体执行接口；以下工具尚未接通真实环境，仍可手工制作后导入。</div><div class="tools-grid"><article class="tool-card" v-for="tool in tools" :key="tool.name"><div class="tool-top"><span class="tool-icon"><Icon :name="tool.icon" :size="27"/></span><span class="badge neutral">未接入</span></div><span class="muted small">{{tool.kind}}</span><h2>{{tool.name}}</h2><p>{{tool.description}}</p><a class="text-link" href="/guides/external-integration.md" target="_blank" rel="noopener">查看接入说明<Icon name="ArrowUpRight" :size="15"/></a></article></div></template>
<template v-else-if="section==='approvals'"><div class="approval-list"><article v-for="item in approvals" :key="item.project.id+item.gate.id" class="approval-card"><span class="approval-step">{{item.gate.id}}</span><div><div class="flex-line"><h2>{{item.gate.name}}</h2><span v-if="item.project.sample" class="badge neutral">示例</span></div><p>{{item.project.title}}</p><small>{{item.gate.decision}}</small></div><div class="approval-actions"><RouterLink class="btn" :to="'/projects/'+item.project.id+'?gate='+item.gate.id">打开材料</RouterLink><template v-if="item.gate.scope==='PLATFORM'"><button v-for="p in item.project.platforms" :key="p" class="btn primary" :disabled="validApproval(item.project,item.gate,p)" @click="approve(item.project.id,item.gate.id,p)"><Icon name="Check" :size="15"/>{{platformName(p)}}{{validApproval(item.project,item.gate,p)?'已确认':'确认'}}</button></template><button v-else class="btn primary" @click="approve(item.project.id,item.gate.id)"><Icon name="Check" :size="15"/>确认当前版本</button></div></article><div v-if="!approvals.length" class="empty-state"><Icon name="CheckCheck" :size="38"/><h2>暂时没有待拍板事项</h2><p>完成对应阶段的材料后，确认请求会出现在这里。</p></div></div><div class="gate-explainer"><h2>你的六个关键决定</h2><div><span v-for="g in store.catalog.gates" :key="g.id"><small>{{g.id}}</small>{{g.name}}</span></div></div></template>
<template v-else-if="section==='tasks'"><div class="info-strip"><Icon name="GitBranch"/><span>下面保留制作计划检查记录。真实 Agent 执行、评审与产物版本在协作运行中查看。</span><RouterLink class="text-link" to="/runs">打开协作运行<Icon name="ArrowUpRight" :size="14"/></RouterLink></div><div class="filter-bar"><div class="segmented"><button v-for="f in [{id:'ALL',name:'全部任务'},{id:'BLOCKED',name:'等待处理'},{id:'COMPLETED',name:'检查完成'},{id:'DELETED',name:'已删除'}]" :key="f.id" :class="{selected:taskFilter===f.id}" @click="taskFilter=f.id">{{f.name}}</button></div><span class="muted small">只有实际操作产生的任务会出现在这里</span></div><div class="task-list"><article v-for="task in tasks" :key="task.id"><span :class="['task-status-icon',task.status]"><Icon :name="task.status==='BLOCKED'?'CirclePause':'CheckCircle2'" :size="20"/></span><div><h3>{{task.title}}<span :class="['badge',task.status==='BLOCKED'?'warning':'success']">{{task.status==='BLOCKED'?'等待处理':'检查完成'}}</span></h3><p>{{task.detail}}</p><small>{{store.state.projects.find(p=>p.id===task.projectId)?.title}} · {{new Date(task.createdAt).toLocaleString('zh-CN')}}</small></div><div class="task-actions"><button v-if="task.deletedAt" class="btn" @click="store.command({type:'RESTORE_TASK',payload:{id:task.id}},'任务已恢复')"><Icon name="RotateCcw" :size="15"/>恢复任务</button><button v-else class="icon-btn danger-text" :aria-label="'删除任务：'+task.title" @click="taskToDelete=task"><Icon name="Trash2" :size="17"/></button><RouterLink v-if="!task.deletedAt" class="icon-btn" :to="'/projects/'+task.projectId+(task.nodeId?'?node='+task.nodeId:'')" aria-label="返回任务节点"><Icon name="ArrowUpRight"/></RouterLink></div></article><div v-if="!tasks.length" class="empty-state"><Icon name="ListTodo" :size="38"/><h2>{{taskFilter==='DELETED'?'没有已删除任务':'制作记录，会在这里发生'}}</h2><p>在作品中点击“检查下一步”或“自动推进”，查看真实的前提检查结果。</p><RouterLink class="btn" to="/projects">返回作品</RouterLink></div></div></template>
<template v-else-if="section==='library'"><input type="file" ref="assetInput" hidden @change="upload"><div class="info-strip"><Icon name="HardDrive"/><span>{{store.connection==='server'?'素材原件保存在后端文件目录':'素材原件保存在此浏览器 IndexedDB'}}。请保存来源与使用授权，并单独备份原件。</span><label class="asset-project-link">上传时关联作品<select v-model="libraryProjectId"><option value="">不关联</option><option v-for="p in store.actualProjects" :key="p.id" :value="p.id">{{p.title}}</option></select></label></div><div class="asset-grid"><button v-for="asset in store.state.assets" :key="asset.id" class="asset-card" @click="view(asset)"><span><Icon :name="asset.type.startsWith('image')?'Image':asset.type.startsWith('video')?'Film':asset.type.startsWith('audio')?'AudioLines':'FileText'" :size="32"/></span><b>{{asset.name}}</b><small>{{(asset.size/1024/1024).toFixed(2)}} MB · {{asset.source}}</small><span class="badge neutral">授权待核查</span></button><button class="upload-tile" @click="($refs.assetInput as HTMLInputElement).click()"><Icon name="Upload" :size="28"/><b>把素材放进来</b><span>图片、视频、音频或文档 · 最大 50MB</span></button></div></template>
<template v-else-if="section==='business'"><div class="business-summary"><div><span>已记录收入</span><strong>¥{{income.toFixed(2)}}</strong></div><div><span>已记录成本</span><strong>¥{{cost.toFixed(2)}}</strong></div><div><span>记录净额</span><strong>¥{{(income-cost).toFixed(2)}}</strong></div></div><div class="info-strip"><Icon name="Info"/>这里仅统计你实际登记的账目，不包含未登记的模型费用。咨询和播放量不会自动计为收入。</div><form class="ledger-form" @submit.prevent="store.command({type:'ADD_LEDGER',payload:{...entry}},'账目已记录')"><label>项目说明<input v-model="entry.label" placeholder="例如：本月配音服务" required></label><label>类型<select v-model="entry.kind"><option value="cost">成本</option><option value="income">收入</option></select></label><label>金额（元）<input type="number" v-model.number="entry.amount" required min="0" step="0.01"></label><button class="btn primary">记录一笔</button></form><div class="ledger-list"><article v-for="e in store.state.ledger" :key="e.id"><span class="ledger-icon"><Icon :name="e.kind==='income'?'ArrowDownLeft':'ArrowUpRight'" :size="18"/></span><div><b>{{e.label}}</b><small>{{new Date(e.createdAt).toLocaleDateString('zh-CN')}}</small></div><strong :class="{positive:e.kind==='income'}">{{e.kind==='income'?'+':'−'}} ¥{{e.amount.toFixed(2)}}</strong></article><p v-if="!store.state.ledger.length" class="empty-copy">还没有账目，从第一笔真实投入开始记录。</p></div></template>
<template v-else-if="section==='creator-profile'"><form class="profile-form form-stack" @submit.prevent="store.command({type:'SAVE_PROFILE',payload:{profile:{...profile}}},'创作档案已保存')"><label v-for="[key,label] in profileFields" :key="key">{{label}}<textarea v-model="profile[key]" rows="3" :placeholder="'记录你的'+label+'，不需要一次想清楚。'"/></label><div class="form-hint"><Icon name="Info" :size="16"/>此处保存创作档案。项目内的节点产物与阶段确认独立记录。</div><button class="btn primary" :disabled="store.saving"><Icon name="Save"/>保存创作档案</button></form></template>
<template v-else><div class="settings-panel"><h2>数据与保存</h2><div class="setting-row"><div><b>当前保存方式</b><p>{{store.connection==='server'?'后端数据库与文件存储':'浏览器 localStorage 与 IndexedDB'}}</p></div><span class="badge success">可用</span></div><div class="setting-row"><div><b>导出工作区数据</b><p>包含作品、节点、模型档案与记录；不包含素材原件或真实密钥。</p></div><button class="btn" @click="store.exportState()"><Icon name="Download" :size="15"/>导出 JSON</button></div><div class="setting-row"><div><b>后端连接</b><p>API 默认 127.0.0.1:8088，通过 Vite 代理。启动服务后刷新页面重新连接。</p></div><span class="badge neutral">{{store.connection==='server'?'已连接':'未启动'}}</span></div></div><div class="settings-panel"><h2>当前版本 · 0.2</h2><p>已实现全流程管理、模型档案与四级绑定、人工产物、版本依赖、阶段确认、任务前提检查、素材上传和基础账目。</p><p>已增加 LangGraph + Deep Agents 真实协作、独立 Skill 与知识、评审返工、持久检查点和人工采纳。当前只开放测试模型；付费模型未验收。远端 ComfyUI、自动渲染、平台发布与指标读取仍未接入。</p><a class="text-link" href="/guides/external-integration.md" target="_blank" rel="noopener">阅读外部接入说明<Icon name="ArrowUpRight" :size="15"/></a></div></template>
<Dialog :open="!!taskToDelete" title="删除这条任务记录？" @close="taskToDelete=null"><p>“{{taskToDelete?.title}}”将移到已删除列表，可以恢复。作品、节点产物与素材不会删除。</p><div class="dialog-actions"><button class="btn" @click="taskToDelete=null">保留任务</button><button class="btn primary" :disabled="store.saving" @click="deleteTask">删除任务记录</button></div></Dialog><Dialog :open="!!preview" :title="preview?.asset.name??'素材预览'" wide @close="closePreview"><template v-if="preview"><img v-if="preview.asset.type.startsWith('image')" :src="preview.url" class="asset-preview" :alt="preview.asset.name"><video v-else-if="preview.asset.type.startsWith('video')" :src="preview.url" controls class="asset-preview"/><audio v-else-if="preview.asset.type.startsWith('audio')" :src="preview.url" controls/><p v-else class="muted">此文件可下载到本机查看。</p><a :href="preview.url" :download="preview.asset.name" class="btn"><Icon name="Download" :size="16"/>下载原件</a></template></Dialog></div></template>
